        /** Đấu bạn: túi đan / phù của khách (id → số), dùng qua core/pvp/items.ts. */
        pvpBag?: Record<string, number>;
        /** Đã ngã (khí huyết về 0): ra khỏi trận. */
        nga?: boolean;
